mapper.insert:
INSERT INTO ${tableName} (id, lock_name)
SELECT #{id}, #{lockName}
WHERE NOT EXISTS (SELECT 1 FROM ${tableName} WHERE lock_name = #{lockName})

mapper.update:
UPDATE ${tableName}
   SET locked_by    = #{ownerId},
       locked_until = #{until},
       hold_count   = CASE WHEN locked_by = #{ownerId} THEN hold_count + 1 ELSE 1 END,
       gmt_modified = NOW()
 WHERE lock_name = #{lockName}
   AND (locked_by IS NULL OR locked_by = #{ownerId}
        OR locked_until IS NULL OR locked_until < #{now})

UPDATE ${tableName}
   SET locked_by    = CASE WHEN hold_count <= 1 THEN NULL ELSE locked_by END,
       locked_until = CASE WHEN hold_count <= 1 THEN NULL ELSE locked_until END,
       hold_count   = hold_count - 1,
       gmt_modified = NOW()
 WHERE lock_name = #{lockName} AND locked_by = #{ownerId}

UPDATE ${tableName}
   SET locked_by = NULL, locked_until = NULL, hold_count = 0, gmt_modified = NOW()
 WHERE lock_name = #{lockName}

mapper.select:
SELECT lock_name AS lockName, locked_by AS ownerId, hold_count AS holdCount,
       locked_until AS lockedUntil, gmt_modified AS gmtModified
FROM ${tableName}
WHERE lock_name = #{lockName}
